// Clean + normalize data
const DATA = RAW_DATA.filter(d => d["OPERATOR NAME"] && d["OPERATOR NAME"] !== "Operator Name").map(d => ({
  name: d["OPERATOR NAME"],
  email: d["OFFICIAL EMAIL"],
  fleetSize: d["FLEET SIZE"],
  operatorType: d["OPERATOR TYPE"],
  aircraftTypes: d["AIRCRAFT TYPES"],
  headquarters: d["HEADQUARTERS"],
  country: d["COUNTRY"] === "United States" ? "USA" : d["COUNTRY"],
  contactNo: d["CONTACT NO"],
  website: d["WEBSITE"],
  region: d["REGION"] === "United States" ? "USA" : d["REGION"],
  category: d["CATEGORY"],
  hasEmail: !!d["OFFICIAL EMAIL"],
  hasContact: !!d["CONTACT NO"],
  hasWebsite: !!d["WEBSITE"],
}));

const CATEGORY_COLORS = {
  "Charter/Business Jet": "#3b82f6",
  "Private": "#8b5cf6",
  "Charter": "#06b6d4",
  "Helicopter/Air Ambulance": "#f59e0b",
  "Cargo": "#10b981",
};

const REGION_COLORS = {
  "USA": "#3b82f6",
  "United Kingdom": "#ef4444",
  "United Arab Emirates": "#f59e0b",
};

const COLS = ["name","category","operatorType","region","country","headquarters","aircraftTypes","contactNo","email","website"];
const COL_LABELS = {
  name:"Operator Name", category:"Category", operatorType:"Type",
  region:"Region", country:"Country", headquarters:"HQ",
  aircraftTypes:"Aircraft Types", contactNo:"Contact", email:"Email", website:"Website"
};

function Badge({ label, color }) {
  return (
    <span style={{
      background: color + "18", color, border: `1px solid ${color}40`,
      borderRadius: 4, padding: "2px 8px", fontSize: 11, fontWeight: 600,
      whiteSpace: "nowrap"
    }}>{label}</span>
  );
}

function StatCard({ label, value, sub, color = "#3b82f6" }) {
  return (
    <div style={{
      background: "#fff", borderRadius: 10, padding: "18px 22px",
      border: "1px solid #e5e7eb", flex: 1, minWidth: 140
    }}>
      <div style={{ fontSize: 28, fontWeight: 700, color, fontFamily: "'Georgia', serif", letterSpacing: -1 }}>{value}</div>
      <div style={{ fontSize: 13, color: "#374151", fontWeight: 600, marginTop: 2 }}>{label}</div>
      {sub && <div style={{ fontSize: 11, color: "#9ca3af", marginTop: 2 }}>{sub}</div>}
    </div>
  );
}

function DetailModal({ operator, onClose }) {
  if (!operator) return null;
  return (
    <div style={{
      position: "fixed", inset: 0, background: "rgba(0,0,0,0.35)",
      zIndex: 1000, display: "flex", alignItems: "center", justifyContent: "center"
    }} onClick={onClose}>
      <div style={{
        background: "#fff", borderRadius: 14, padding: 32, maxWidth: 560, width: "90%",
        boxShadow: "0 20px 60px rgba(0,0,0,0.15)", position: "relative"
      }} onClick={e => e.stopPropagation()}>
        <button onClick={onClose} style={{
          position: "absolute", top: 14, right: 14,
          background: "#f3f4f6", border: "none", borderRadius: 6,
          cursor: "pointer", padding: "4px 10px", fontSize: 16, color: "#6b7280"
        }}>✕</button>
        <div style={{ marginBottom: 6 }}>
          <Badge label={operator.category} color={CATEGORY_COLORS[operator.category] || "#6b7280"} />
        </div>
        <h2 style={{ fontSize: 20, fontWeight: 700, margin: "8px 0 16px", fontFamily: "'Georgia', serif" }}>
          {operator.name}
        </h2>
        {[
          ["Operator Type", operator.operatorType],
          ["Region / Country", `${operator.region} — ${operator.country}`],
          ["Headquarters", operator.headquarters],
          ["Aircraft Types", operator.aircraftTypes],
          ["Fleet Size", operator.fleetSize],
          ["Contact", operator.contactNo],
          ["Email", operator.email],
          ["Website", operator.website],
        ].map(([k, v]) => v ? (
          <div key={k} style={{ display: "flex", gap: 12, marginBottom: 8, fontSize: 13 }}>
            <span style={{ color: "#9ca3af", minWidth: 120, fontWeight: 500 }}>{k}</span>
            <span style={{ color: "#111827", wordBreak: "break-word" }}>{v}</span>
          </div>
        ) : null)}
        <div style={{ marginTop: 16, display: "flex", gap: 8 }}>
          {operator.hasEmail && <Badge label="✓ Has Email" color="#10b981" />}
          {operator.hasContact && <Badge label="✓ Has Phone" color="#3b82f6" />}
          {operator.hasWebsite && <Badge label="✓ Has Website" color="#8b5cf6" />}
        </div>
      </div>
    </div>
  );
}

export default function App() {
  const [search, setSearch] = useState("");
  const [filterRegion, setFilterRegion] = useState("All");
  const [filterCat, setFilterCat] = useState("All");
  const [filterContact, setFilterContact] = useState("All");
  const [activeTab, setActiveTab] = useState("overview");
  const [selectedOp, setSelectedOp] = useState(null);
  const [sortCol, setSortCol] = useState("name");
  const [sortDir, setSortDir] = useState("asc");
  const [page, setPage] = useState(0);
  const PAGE_SIZE = 20;

  const regions = ["All", ...Array.from(new Set(DATA.map(d => d.region))).sort()];
  const cats = ["All", ...Array.from(new Set(DATA.map(d => d.category))).sort()];

  const filtered = useMemo(() => {
    let d = DATA;
    if (filterRegion !== "All") d = d.filter(x => x.region === filterRegion);
    if (filterCat !== "All") d = d.filter(x => x.category === filterCat);
    if (filterContact === "Email") d = d.filter(x => x.hasEmail);
    if (filterContact === "Phone") d = d.filter(x => x.hasContact);
    if (filterContact === "Both") d = d.filter(x => x.hasEmail && x.hasContact);
    if (search.trim()) {
      const q = search.toLowerCase();
      d = d.filter(x =>
        x.name.toLowerCase().includes(q) ||
        (x.headquarters || "").toLowerCase().includes(q) ||
        (x.aircraftTypes || "").toLowerCase().includes(q) ||
        (x.operatorType || "").toLowerCase().includes(q)
      );
    }
    return [...d].sort((a, b) => {
      const av = (a[sortCol] || "").toString().toLowerCase();
      const bv = (b[sortCol] || "").toString().toLowerCase();
      return sortDir === "asc" ? av.localeCompare(bv) : bv.localeCompare(av);
    });
  }, [search, filterRegion, filterCat, filterContact, sortCol, sortDir]);

  const paginated = filtered.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE);
  const totalPages = Math.ceil(filtered.length / PAGE_SIZE);

  // Chart data
  const categoryData = useMemo(() =>
    Object.entries(DATA.reduce((acc, d) => {
      acc[d.category] = (acc[d.category] || 0) + 1; return acc;
    }, {})).map(([name, value]) => ({ name, value })).sort((a,b) => b.value - a.value)
  , []);

  const regionData = useMemo(() =>
    Object.entries(DATA.reduce((acc, d) => {
      acc[d.region] = (acc[d.region] || 0) + 1; return acc;
    }, {})).map(([name, value]) => ({ name, value }))
  , []);

  const contactData = [
    { name: "Has Email", value: DATA.filter(d => d.hasEmail).length },
    { name: "Has Phone", value: DATA.filter(d => d.hasContact).length },
    { name: "Has Website", value: DATA.filter(d => d.hasWebsite).length },
    { name: "No Contact", value: DATA.filter(d => !d.hasEmail && !d.hasContact).length },
  ];

  const opTypeData = useMemo(() => {
    const counts = DATA.reduce((acc, d) => {
      const t = d.operatorType || "Unknown";
      acc[t] = (acc[t] || 0) + 1; return acc;
    }, {});
    return Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,10)
      .map(([name, value]) => ({ name: name.length > 22 ? name.slice(0,22)+"…" : name, value }));
  }, []);

  const handleSort = col => {
    if (sortCol === col) setSortDir(d => d === "asc" ? "desc" : "asc");
    else { setSortCol(col); setSortDir("asc"); }
    setPage(0);
  };

  const tabStyle = (t) => ({
    padding: "8px 20px", borderRadius: 7, border: "none",
    background: activeTab === t ? "#1e40af" : "transparent",
    color: activeTab === t ? "#fff" : "#6b7280",
    fontWeight: 600, cursor: "pointer", fontSize: 14,
    transition: "all .15s"
  });

  return (
    <div style={{ fontFamily: "'Segoe UI', system-ui, sans-serif", background: "#f8fafc", minHeight: "100vh", padding: 0 }}>
      {/* Header */}
      <div style={{
        background: "#fff", borderBottom: "1px solid #e5e7eb",
        padding: "16px 28px", display: "flex", alignItems: "center", gap: 16
      }}>
        <div style={{
          width: 36, height: 36, background: "#1e40af", borderRadius: 8,
          display: "flex", alignItems: "center", justifyContent: "center",
          fontSize: 18
        }}>✈</div>
        <div>
          <div style={{ fontWeight: 700, fontSize: 17, color: "#111827", fontFamily: "'Georgia', serif" }}>
            FAR Operators Intelligence Dashboard
          </div>
          <div style={{ fontSize: 12, color: "#9ca3af" }}>Global Aircraft Operator Database · {DATA.length} operators · Internal Use Only</div>
        </div>
        <div style={{ marginLeft: "auto", display: "flex", gap: 8 }}>
          {["overview", "table"].map(t => (
            <button key={t} style={tabStyle(t)} onClick={() => setActiveTab(t)}>
              {t === "overview" ? "📊 Overview" : "📋 Operator Table"}
            </button>
          ))}
        </div>
      </div>

      <div style={{ padding: "24px 28px" }}>
        {activeTab === "overview" && (
          <>
            {/* KPI cards */}
            <div style={{ display: "flex", gap: 14, flexWrap: "wrap", marginBottom: 24 }}>
              <StatCard label="Total Operators" value={DATA.length} sub="Across all regions" color="#1e40af" />
              <StatCard label="USA Operators" value={DATA.filter(d=>d.region==="USA").length} sub="FAR 125 / 135 / Corporate" color="#3b82f6" />
              <StatCard label="UK Operators" value={DATA.filter(d=>d.region==="United Kingdom").length} sub="Charter, Heli, Cargo" color="#ef4444" />
              <StatCard label="UAE Operators" value={DATA.filter(d=>d.region==="United Arab Emirates").length} sub="Cargo, Charter, Heli" color="#f59e0b" />
              <StatCard label="Has Email" value={DATA.filter(d=>d.hasEmail).length} sub={`${((DATA.filter(d=>d.hasEmail).length/DATA.length)*100).toFixed(0)}% contact rate`} color="#10b981" />
              <StatCard label="Has Phone" value={DATA.filter(d=>d.hasContact).length} sub={`${((DATA.filter(d=>d.hasContact).length/DATA.length)*100).toFixed(0)}% reachable`} color="#8b5cf6" />
            </div>

            {/* Charts row 1 */}
            <div style={{ display: "flex", gap: 18, marginBottom: 18, flexWrap: "wrap" }}>
              {/* Category pie */}
              <div style={{ flex: 1, minWidth: 280, background: "#fff", borderRadius: 10, padding: 20, border: "1px solid #e5e7eb" }}>
                <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 14, color: "#111827" }}>Operators by Category</div>
                <ResponsiveContainer width="100%" height={220}>
                  <PieChart>
                    <Pie data={categoryData} dataKey="value" nameKey="name" cx="50%" cy="50%" outerRadius={85} label={({name, percent}) => `${(percent*100).toFixed(0)}%`} labelLine={false}>
                      {categoryData.map((entry) => (
                        <Cell key={entry.name} fill={CATEGORY_COLORS[entry.name] || "#94a3b8"} />
                      ))}
                    </Pie>
                    <Tooltip formatter={(v, n) => [v, n]} />
                  </PieChart>
                </ResponsiveContainer>
                <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginTop: 8 }}>
                  {categoryData.map(d => (
                    <div key={d.name} style={{ display: "flex", alignItems: "center", gap: 5, fontSize: 11, color: "#374151" }}>
                      <div style={{ width: 8, height: 8, borderRadius: 2, background: CATEGORY_COLORS[d.name] || "#94a3b8", flexShrink: 0 }} />
                      {d.name} ({d.value})
                    </div>
                  ))}
                </div>
              </div>

              {/* Region bar */}
              <div style={{ flex: 1, minWidth: 280, background: "#fff", borderRadius: 10, padding: 20, border: "1px solid #e5e7eb" }}>
                <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 14, color: "#111827" }}>Operators by Region</div>
                <ResponsiveContainer width="100%" height={220}>
                  <BarChart data={regionData} layout="vertical" margin={{ left: 20, right: 20 }}>
                    <XAxis type="number" tick={{ fontSize: 11 }} />
                    <YAxis type="category" dataKey="name" tick={{ fontSize: 12 }} width={130} />
                    <Tooltip />
                    <Bar dataKey="value" radius={[0, 4, 4, 0]}>
                      {regionData.map((entry) => (
                        <Cell key={entry.name} fill={REGION_COLORS[entry.name] || "#94a3b8"} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </div>

              {/* Contact availability */}
              <div style={{ flex: 1, minWidth: 280, background: "#fff", borderRadius: 10, padding: 20, border: "1px solid #e5e7eb" }}>
                <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 14, color: "#111827" }}>Contact Availability</div>
                <ResponsiveContainer width="100%" height={220}>
                  <BarChart data={contactData}>
                    <XAxis dataKey="name" tick={{ fontSize: 11 }} />
                    <YAxis tick={{ fontSize: 11 }} />
                    <Tooltip />
                    <Bar dataKey="value" fill="#3b82f6" radius={[4,4,0,0]}>
                      {contactData.map((entry, i) => (
                        <Cell key={i} fill={["#10b981","#3b82f6","#8b5cf6","#f59e0b"][i]} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </div>

            {/* Op type breakdown */}
            <div style={{ background: "#fff", borderRadius: 10, padding: 20, border: "1px solid #e5e7eb" }}>
              <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 14, color: "#111827" }}>Top Operator Types</div>
              <ResponsiveContainer width="100%" height={220}>
                <BarChart data={opTypeData}>
                  <XAxis dataKey="name" tick={{ fontSize: 10 }} angle={-20} textAnchor="end" interval={0} height={55} />
                  <YAxis tick={{ fontSize: 11 }} />
                  <Tooltip />
                  <Bar dataKey="value" fill="#1e40af" radius={[4,4,0,0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </>
        )}

        {activeTab === "table" && (
          <>
            {/* Filters */}
            <div style={{
              background: "#fff", borderRadius: 10, padding: "14px 18px",
              border: "1px solid #e5e7eb", marginBottom: 16,
              display: "flex", gap: 12, flexWrap: "wrap", alignItems: "center"
            }}>
              <input
                value={search}
                onChange={e => { setSearch(e.target.value); setPage(0); }}
                placeholder="Search operators, HQ, aircraft type..."
                style={{
                  flex: 2, minWidth: 220, padding: "8px 12px", borderRadius: 7,
                  border: "1px solid #d1d5db", fontSize: 13, outline: "none",
                  color: "#111827"
                }}
              />
              {[
                ["Region", filterRegion, setFilterRegion, regions],
                ["Category", filterCat, setFilterCat, cats],
              ].map(([label, val, setter, opts]) => (
                <select key={label} value={val} onChange={e => { setter(e.target.value); setPage(0); }}
                  style={{ padding: "8px 12px", borderRadius: 7, border: "1px solid #d1d5db", fontSize: 13, color: "#374151", background: "#fff" }}>
                  {opts.map(o => <option key={o}>{o}</option>)}
                </select>
              ))}
              <select value={filterContact} onChange={e => { setFilterContact(e.target.value); setPage(0); }}
                style={{ padding: "8px 12px", borderRadius: 7, border: "1px solid #d1d5db", fontSize: 13, color: "#374151", background: "#fff" }}>
                {["All", "Email", "Phone", "Both"].map(o => <option key={o}>{o}</option>)}
              </select>
              <div style={{ marginLeft: "auto", fontSize: 12, color: "#6b7280", fontWeight: 500 }}>
                {filtered.length} of {DATA.length} operators
              </div>
            </div>

            {/* Summary cards for filtered */}
            <div style={{ display: "flex", gap: 12, marginBottom: 16, flexWrap: "wrap" }}>
              {Object.entries(
                filtered.reduce((a,d) => { a[d.category] = (a[d.category]||0)+1; return a; }, {})
              ).sort((a,b)=>b[1]-a[1]).map(([cat, cnt]) => (
                <div key={cat} style={{
                  background: "#fff", borderRadius: 8, padding: "10px 16px",
                  border: `1.5px solid ${CATEGORY_COLORS[cat] || "#94a3b8"}40`,
                  display: "flex", alignItems: "center", gap: 8
                }}>
                  <div style={{ width: 8, height: 8, borderRadius: 2, background: CATEGORY_COLORS[cat] || "#94a3b8" }} />
                  <span style={{ fontSize: 12, color: "#374151", fontWeight: 600 }}>{cat}</span>
                  <span style={{ fontSize: 12, color: "#9ca3af" }}>{cnt}</span>
                </div>
              ))}
            </div>

            {/* Table */}
            <div style={{ background: "#fff", borderRadius: 10, border: "1px solid #e5e7eb", overflow: "auto" }}>
              <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
                <thead>
                  <tr style={{ background: "#f9fafb" }}>
                    {["name","category","region","operatorType","headquarters","aircraftTypes","contactNo","email"].map(col => (
                      <th key={col}
                        onClick={() => handleSort(col)}
                        style={{
                          padding: "10px 14px", textAlign: "left", fontWeight: 600,
                          color: "#374151", cursor: "pointer", whiteSpace: "nowrap",
                          borderBottom: "1px solid #e5e7eb", userSelect: "none",
                          background: sortCol === col ? "#f0f9ff" : undefined
                        }}>
                        {COL_LABELS[col]} {sortCol === col ? (sortDir === "asc" ? "↑" : "↓") : ""}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {paginated.map((op, i) => (
                    <tr key={i}
                      onClick={() => setSelectedOp(op)}
                      style={{
                        borderBottom: "1px solid #f3f4f6", cursor: "pointer",
                        background: i % 2 === 0 ? "#fff" : "#fafafa",
                        transition: "background .1s"
                      }}
                      onMouseEnter={e => e.currentTarget.style.background = "#eff6ff"}
                      onMouseLeave={e => e.currentTarget.style.background = i % 2 === 0 ? "#fff" : "#fafafa"}
                    >
                      <td style={{ padding: "9px 14px", fontWeight: 600, color: "#111827", maxWidth: 220 }}>
                        <div style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{op.name}</div>
                      </td>
                      <td style={{ padding: "9px 14px" }}>
                        <Badge label={op.category} color={CATEGORY_COLORS[op.category] || "#94a3b8"} />
                      </td>
                      <td style={{ padding: "9px 14px", color: "#6b7280" }}>{op.region}</td>
                      <td style={{ padding: "9px 14px", color: "#6b7280", maxWidth: 160 }}>
                        <div style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{op.operatorType}</div>
                      </td>
                      <td style={{ padding: "9px 14px", color: "#6b7280", maxWidth: 160 }}>
                        <div style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{op.headquarters || "—"}</div>
                      </td>
                      <td style={{ padding: "9px 14px", color: "#6b7280", maxWidth: 180 }}>
                        <div style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{op.aircraftTypes || "—"}</div>
                      </td>
                      <td style={{ padding: "9px 14px", color: op.hasContact ? "#10b981" : "#d1d5db" }}>
                        {op.contactNo ? <span title={op.contactNo}>📞</span> : "—"}
                      </td>
                      <td style={{ padding: "9px 14px", color: op.hasEmail ? "#10b981" : "#d1d5db" }}>
                        {op.email ? <span title={op.email}>✉</span> : "—"}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>

              {/* Pagination */}
              <div style={{
                display: "flex", alignItems: "center", justifyContent: "space-between",
                padding: "12px 18px", borderTop: "1px solid #f3f4f6"
              }}>
                <span style={{ fontSize: 12, color: "#9ca3af" }}>
                  Showing {page * PAGE_SIZE + 1}–{Math.min((page+1)*PAGE_SIZE, filtered.length)} of {filtered.length}
                </span>
                <div style={{ display: "flex", gap: 6 }}>
                  <button onClick={() => setPage(p => Math.max(0, p-1))} disabled={page === 0}
                    style={{ padding: "5px 12px", borderRadius: 6, border: "1px solid #d1d5db", background: "#fff", cursor: page===0?"not-allowed":"pointer", fontSize: 13, color: "#374151" }}>
                    ← Prev
                  </button>
                  {Array.from({length: Math.min(5, totalPages)}, (_,i) => {
                    const pg = Math.max(0, Math.min(page - 2, totalPages - 5)) + i;
                    return (
                      <button key={pg} onClick={() => setPage(pg)}
                        style={{
                          padding: "5px 10px", borderRadius: 6, border: "1px solid #d1d5db",
                          background: page === pg ? "#1e40af" : "#fff",
                          color: page === pg ? "#fff" : "#374151",
                          cursor: "pointer", fontSize: 13, fontWeight: page===pg?700:400
                        }}>
                        {pg + 1}
                      </button>
                    );
                  })}
                  <button onClick={() => setPage(p => Math.min(totalPages-1, p+1))} disabled={page >= totalPages-1}
                    style={{ padding: "5px 12px", borderRadius: 6, border: "1px solid #d1d5db", background: "#fff", cursor: page>=totalPages-1?"not-allowed":"pointer", fontSize: 13, color: "#374151" }}>
                    Next →
                  </button>
                </div>
              </div>
            </div>
            <div style={{ marginTop: 10, fontSize: 11, color: "#9ca3af", textAlign: "right" }}>
              Click any row to view full operator details
            </div>
          </>
        )}
      </div>

      <DetailModal operator={selectedOp} onClose={() => setSelectedOp(null)} />
    </div>
  );
}
